SOLAR_TERMS='小寒 大寒 立春 雨水 惊蛰 春分 清明 谷雨 立夏 小满 芒种 夏至 小暑 大暑 立秋 处暑 白露 秋分 寒露 霜降 立冬 小雪 大雪 冬至'.split()
SOLAR_FESTIVALS={(1,1):'元旦',(2,14):'情人节',(3,8):'妇女节',(3,12):'植树节',
                 (5,1):'劳动节',(5,4):'青年节',(6,1):'儿童节',(7,1):'建党节',
                 (8,1):'建军节',(9,10):'教师节',(10,1):'国庆节',(12,25):'圣诞节'}
LUNAR_FESTIVALS={(1,1):'春节',(1,15):'元宵节',(2,2):'龙抬头',(5,5):'端午节',
                 (7,7):'七夕',(7,15):'中元节',(8,15):'中秋节',(9,9):'重阳节',(12,8):'腊八节'}

@lru_cache(maxsize=4)
def lunar_date(day):
    """Return year, signed month (negative for leap), day, and month length."""
    if not 1901<=day.year<=2100: return None
    ordinal=day.toordinal()
    index=bisect_right(LUNAR_STARTS,ordinal)-1
    start,leap,bits=LUNAR_YEARS[index]
    offset=ordinal-start; position=0
    for month in range(1,13):
        for signed_month in ((month,-month) if month==leap else (month,)):
            length=29+((bits>>position)&1)
            if offset<length: return (1900+index,signed_month,offset+1,length)
            offset-=length; position+=1
    return None

LUNAR_STARTS=tuple(row[0] for row in LUNAR_YEARS)

@lru_cache(maxsize=4)
def calendar_labels(day):
    """Local date labels, with festivals on their actual day, never leap repeats."""
    lunar=lunar_date(day); lunar_label=''; festivals=[]; term=''
    solar_festival=SOLAR_FESTIVALS.get((day.month,day.day))
    if solar_festival: festivals.append(solar_festival)
    if day.weekday()==6:
        if day.month==5 and 8<=day.day<=14: festivals.append('母亲节')
        if day.month==6 and 15<=day.day<=21: festivals.append('父亲节')
    if lunar:
        year,month,number,length=lunar
        months=('正','二','三','四','五','六','七','八','九','十','冬','腊')
        digits='一二三四五六七八九十'
        if number<=10: day_label='初'+digits[number-1]
        elif number<20: day_label='十'+digits[number-11]
        elif number==20: day_label='二十'
        elif number<30: day_label='廿'+digits[number-21]
        else: day_label='三十'
        lunar_label='农历 '+('闰' if month<0 else '')+months[abs(month)-1]+'月'+day_label
        festival=LUNAR_FESTIVALS.get((month,number))
        if festival: festivals.append(festival)
        if month==12 and number==length: festivals.append('除夕')
    if 1901<=day.year<=2100:
        days=SOLAR_TERM_DAYS[day.year-1901]
        for index in ((day.month-1)*2,(day.month-1)*2+1):
            if day.day==int(days[2*index:2*index+2]): term=SOLAR_TERMS[index]
    return lunar_label,tuple(festivals),term

def weather_name(code):
    if code == 0: return '晴'
    if code in (1,2): return '多云'
    if code == 3: return '阴'
    if code in (45,48): return '雾'
    if code in (51,53,55,56,57): return '毛毛雨'
    if code in (61,63,65,66,67,80,81,82): return '雨'
    if code in (71,73,75,77,85,86): return '雪'
    if code in (95,96,99): return '雷雨'
    return '天气待更新'

@lru_cache(maxsize=32)
def font(size,bold=False,numeric=False):
    name='SourceHanSansCN-Bold.otf' if bold else 'SourceHanSansCN-Regular.otf'
    # Older personal installations keep working until fonts are migrated over USB.
    if not (FONT_ASSETS/name).is_file():
        name=('arialbd.ttf' if bold else 'arial.ttf') if numeric else ('msyhbd.ttc' if bold else 'msyh.ttc')
    return ImageFont.truetype(str(FONT_ASSETS/name),size)

def fit_text(draw, value, size, width, bold=False):
    face = font(size,bold)
    # Headlines and agenda cells are single-line, even when their source is not.
    result = ' '.join(str(value or '').split())
    if width<=0: return ''
    if draw.textlength(result,font=face)<=width: return result
    if draw.textlength('…',font=face)>width: return ''
    low,high=0,len(result)
    while low<high:
        middle=(low+high+1)//2
        if draw.textlength(result[:middle]+'…',font=face)<=width: low=middle
        else: high=middle-1
    return result[:low]+'…'

def parsed_time(value):
    try:
        value=datetime.fromisoformat(value)
        return value.replace(tzinfo=TZ) if value.tzinfo is None else value
    except (TypeError,ValueError): return None

def news_items(value):
    if not isinstance(value,list): return []
    return [item for item in value if isinstance(item,dict) and isinstance(item.get('name'),str) and item['name'].strip()][:NEWS_LIMIT]

def enabled_news(config,items):
    settings=config.get('settings') or {}
    sources={
        '华尔街见闻':settings.get('news_wallstreetcn',True),
        '东方财富':settings.get('news_eastmoney',True),
    }
    return [item for item in items if sources.get(item.get('source'),True)]

def merge_news_history(previous,incoming=(),current=None,fallback=None):
    """Bound history by publication age; unknown dates expire from first seen."""
    stamp=(current or now()).timestamp()
    def timestamp(value):
        try:
            number=float(value)
            return number if math.isfinite(number) and 0<number<=stamp+300 else None
        except (TypeError,ValueError,OverflowError): return None
    fallback=timestamp(fallback) or stamp
    unique={}
    for raw in news_items(previous)+news_items(list(incoming)):
        name=raw['name'][:2000]
        url=str(raw.get('url') or '')[:2048]
        source=str(raw.get('source') or '')[:60]
        key=url or (source,name)
        old=unique.get(key,{})
        seen=timestamp(old.get('seen_at')) or timestamp(raw.get('seen_at')) or fallback
        published=timestamp(raw.get('time'))
        retained=published or seen
        if retained<stamp-NEWS_MAX_AGE: continue
        item=dict(name=name,url=url,source=source,time=int(published or 0),seen_at=seen)
        content=str(raw.get('content') or old.get('content') or '')
        if content: item['content']=content[:12000]+('…（更多内容请用手机查看原文）' if len(content)>12000 else '')
        unique[key]=item
    return sorted(unique.values(),key=lambda v:v['time'] or v['seen_at'],reverse=True)[:NEWS_LIMIT]

def clock_text(moment,time_format='24'):
    if time_format=='12':
        suffix='AM' if moment.hour<12 else 'PM'
        return f'{moment.hour%12 or 12:02d}:{moment.minute:02d} {suffix}'
    return moment.strftime('%H:%M')

def event_time(value,time_format='24'):
    if not value: return '全天'
    try: return clock_text(datetime.strptime(str(value),'%H:%M'),time_format)
    except (TypeError,ValueError): return str(value)

def fmt_news_time(value,current,time_format='24'):
    try: moment=datetime.fromtimestamp(int(value),TZ)
    except (TypeError,ValueError,OSError,OverflowError): return ''
    if moment.date()==current.date(): return clock_text(moment,time_format)
    return moment.strftime('%m/%d')

def fmt_news_full(value,time_format='24'):
    try:
        moment=datetime.fromtimestamp(int(value),TZ)
        return moment.strftime('%m-%d')+' '+clock_text(moment,time_format)
    except (TypeError,ValueError,OSError,OverflowError): return ''

_MEASURE=ImageDraw.Draw(Image.new('L',(8,8)))

def wrap_lines(text,size,width,bold=False):
    lines=[]
    for raw in str(text).splitlines() or ['']:
        line=''
        for ch in raw:
            if _MEASURE.textlength(line+ch,font=font(size,bold))<=width: line+=ch
            else:
                lines.append(line); line=ch
        lines.append(line)
    return lines or ['']

def paginate(text,size=22,width=540,per_page=14):
    lines=wrap_lines(text,size,width)
    return [lines[i:i+per_page] for i in range(0,len(lines),per_page)] or [[]]

def future_events(config,current):
    future=[]
    for event in config['events']:
        try:
            date=datetime.strptime(event['date'],'%Y-%m-%d').date()
            event_time=event.get('time','')
            if date>current.date() or (date==current.date() and (not event_time or event_time>=current.strftime('%H:%M'))):
                future.append(event)
        except (KeyError,ValueError): continue
    future.sort(key=lambda e:(e['date'],e.get('time','') or '00:00',e['id']))
    return future

BUTTON_ICONS={'返回':'back','取消':'back','放弃':'close','上一页':'prev','下一页':'next',
              '上个月':'prev','下个月':'next','本月':'today','新增':'plus','日历':'calendar',
              '全部日程':'list','刷新':'refresh','扫描':'refresh','修改':'edit','删除':'trash',
              '确认删除':'check','保存':'check','下一项':'next_field','暂停':'pause','继续':'play',
              '开始':'play','重置':'reset','再来一轮':'reset','立即待机':'standby'}

def action_icon(d,name,cx,cy,size=28,fill=0):
    """Stroke icons do not depend on Unicode glyph coverage on the Kindle."""
    scale=size/32
    def box(values): return tuple(round((cx if i%2==0 else cy)+(v-16)*scale) for i,v in enumerate(values))
    width=max(2,round(3*scale))
    def line(values): d.line(box(values),fill=fill,width=width)
    def rect(values): d.rectangle(box(values),outline=fill,width=width)
    if name in ('back','prev','next','next_field'):
        if name in ('back','prev'):
            line((22,5,11,16,22,27))
            if name=='back': line((11,16,30,16))
        else:
            line((10,5,21,16,10,27))
            if name=='next_field': line((27,5,27,27))
    elif name in ('plus','minus'):
        line((5,16,27,16))
        if name=='plus': line((16,5,16,27))
    elif name=='play': d.polygon(box((7,4,27,16,7,28)),fill=fill)
    elif name=='pause':
        d.rectangle(box((6,5,12,27)),fill=fill); d.rectangle(box((20,5,26,27)),fill=fill)
    elif name=='check': line((4,16,12,25,28,6))
    elif name=='close': line((6,6,26,26)); line((6,26,26,6))
    elif name in ('calendar','today'):
        rect((3,6,29,29)); line((3,13,29,13)); line((10,2,10,10)); line((22,2,22,10))
        if name=='today': d.ellipse(box((12,18,20,26)),fill=fill)
        else:
            for x,y in ((10,19),(21,19),(10,25),(21,25)): d.rectangle(box((x-1,y-1,x+1,y+1)),fill=fill)
    elif name=='list':
        for y in (7,16,25):
            d.rectangle(box((3,y-1,5,y+1)),fill=fill); line((10,y,29,y))
    elif name=='trash':
        line((3,8,29,8)); line((11,8,11,3,21,3,21,8))
        line((7,9,9,29,23,29,25,9)); line((13,13,13,24)); line((19,13,19,24))
    elif name=='edit':
        d.polygon(box((7,21,22,6,28,12,13,27,5,29)),outline=fill)
        line((7,21,13,27)); line((20,8,26,14)); line((6,25,9,28))
    elif name in ('refresh','reset'):
        if name=='refresh':
            d.arc(box((4,4,28,28)),40,320,fill=fill,width=width)
            line((28,2,27,12,18,9))
        else:
            d.arc(box((4,4,28,28)),220,500,fill=fill,width=width)
            line((4,2,5,12,14,9))
    elif name=='settings':
        for angle in range(0,360,45):
            a=math.radians(angle)
            line((16+8*math.cos(a),16+8*math.sin(a),16+14*math.cos(a),16+14*math.sin(a)))
        d.ellipse(box((8,8,24,24)),outline=fill,width=width)
        d.ellipse(box((13,13,19,19)),outline=fill,width=width)
    elif name=='wifi':
        d.arc(box((3,11,29,37)),225,315,fill=fill,width=width)
        d.arc(box((8,16,24,32)),225,315,fill=fill,width=width)
        d.ellipse(box((14,22,18,26)),fill=fill)
    elif name=='phone':
        d.rounded_rectangle(box((7,2,25,30)),radius=max(1,round(3*scale)),outline=fill,width=width)
        line((13,6,19,6)); d.ellipse(box((15,25,17,27)),fill=fill)
    elif name=='standby':
        d.arc(box((5,5,27,27)),-45,225,fill=fill,width=width)
        line((16,2,16,16))
    elif name=='space': line((5,12,5,23,27,23,27,12))
    elif name=='backspace':
        d.polygon(box((2,16,10,6,30,6,30,26,10,26)),outline=fill)
        line((15,11,24,21)); line((15,21,24,11))

def icon_button(d,box,name,size=28,disabled=False):
    fill=175 if disabled else 0
    d.rounded_rectangle(box,radius=5,outline=fill,width=2)
    action_icon(d,name,(box[0]+box[2])/2,(box[1]+box[3])/2,size,fill)

def _draw_buttons(d,labels):
    for x,label in zip((30,214,398),labels):
        if not label: continue
        name=BUTTON_ICONS.get(label)
        if name: icon_button(d,(x,728,x+172,777),name)
        else:
            d.rectangle((x,728,x+172,777),outline=0,width=2)
            d.text((x+86,742),label,font=font(18,True),fill=0,anchor='mt')

def render_news_detail(item,page,pages,current=None,time_format='24'):
    current=current or now()
    image=Image.new('L',(600,800),255)
    d=ImageDraw.Draw(image)
    weibo=item.get('source')=='微博热搜'
    d.text((30,25),'微博热搜' if weibo else 'AI 金融资讯',font=font(20,True),fill=0,anchor='lt')
    when=fmt_news_full(item.get('time'),time_format)
    meta=('加载中' if item.get('detail_loading') else '相关新闻摘要') if weibo else (item.get('source') or '')+((' · '+when) if when else '')
    d.text((502 if weibo else 570,28),fit_text(d,meta,14,300 if weibo else 360),font=font(14),fill=80,anchor='rt')
    if weibo: action_icon(d,'refresh',551,36,26,160 if item.get('detail_loading') else 0)
    d.line((30,58,570,58),fill=0,width=2)
    total=max(1,len(pages))
    page=max(0,min(page,total-1))
    yy=84
    for line in pages[page]:
        d.text((30,yy),line,font=font(24),fill=0,anchor='lt'); yy+=38
    if total>1:
        d.text((570,700),f'第 {page+1} / {total} 页',font=font(14),fill=110,anchor='rt')
    _draw_buttons(d,('返回','上一页' if page>0 else '','下一页' if page<total-1 else ''))
    return image

def render_event_detail(event,confirm,current=None,message='',time_format='24'):
    current=current or now()
    image=Image.new('L',(600,800),255)
    d=ImageDraw.Draw(image)
    d.text((30,25),'日程详情',font=font(20,True),fill=0,anchor='lt')
    d.line((30,58,570,58),fill=0,width=2)
    try:
        edate=datetime.strptime(event['date'],'%Y-%m-%d').date()
        dlabel=event['date']+' 周'+'一二三四五六日'[edate.weekday()]
    except (ValueError,KeyError):
        dlabel=event.get('date','')
    d.text((30,95),dlabel,font=font(34,True),fill=0,anchor='lt')
    d.text((30,160),event_time(event.get('time'),time_format),font=font(26,True),fill=0,anchor='lt')
    y=225
    bottom=520 if confirm or message else 680
    truncated=False
    for line in wrap_lines(event.get('title') or '',26,540,True):
        if y+30>bottom: truncated=True; break
        d.text((30,y),line,font=font(26,True),fill=0,anchor='lt'); y+=40
    note=event.get('note') or ''
    if note:
        y+=12
        for line in wrap_lines(note,20,540):
            if y+24>bottom: truncated=True; break
            d.text((30,y),line,font=font(20),fill=80,anchor='lt'); y+=32
    if truncated:
        d.text((30,bottom+5),'更多内容请在日程管理中查看。',font=font(16),fill=80,anchor='lt')
    if message:
        for i,line in enumerate(wrap_lines(message,20,540)[:4]):
            d.text((30,570+i*30),line,font=font(20),fill=0,anchor='lt')
        _draw_buttons(d,('返回','',''))
    elif confirm:
        d.text((30,570),'确认删除这条日程？',font=font(22,True),fill=0,anchor='lt')
        d.text((30,606),'确认日期和内容后，点右下角勾号。',font=font(16),fill=80,anchor='lt')
        _draw_buttons(d,('取消','','确认删除'))
    else:
        _draw_buttons(d,('返回','修改','删除'))
    return image

def icon(draw, code, x, y, scale=1):
    def box(values): return tuple(round((x if i%2==0 else y)+v*scale) for i,v in enumerate(values))
    def line(values,w=3): draw.line(box(values), fill=0,width=max(1,round(w*scale)))
    if code in (0,1,2):
        draw.ellipse(box((23,18,55,50)),outline=0,width=max(1,round(3*scale)))
        for angle in range(0,360,45):
            a=math.radians(angle)
            line((39+23*math.cos(a),34+23*math.sin(a),39+31*math.cos(a),34+31*math.sin(a)))
    if code != 0:
        for ellipse in ((19,35,54,67),(37,26,76,67),(59,40,88,67)):
            draw.ellipse(box(ellipse),fill=255,outline=0,width=max(1,round(3*scale)))
        draw.rectangle(box((25,51,81,65)),fill=255)
        line((25,66,81,66))
        if code >= 51 and code not in (71,73,75,77,85,86):
            for dx in (31,52,73): line((dx,76,dx-5,87))
        if code in (71,73,75,77,85,86):
            for dx in (31,52,73):
                line((dx,74,dx,86),2); line((dx-5,80,dx+5,80),2)

def checkbox(d,x,y,size,checked=False):
    d.rectangle((x,y,x+size,y+size),outline=0,width=2)
    if checked:
        d.line((x+5,y+size//2,x+size//2-2,y+size-6,x+size-5,y+5),fill=0,width=3)

def todo_items(config,done=None):
    items=config.get('todos',[])
    if done is not None: return [e for e in items if bool(e.get('done'))==done]
    return [e for e in items if not e.get('done')]+sorted(
        [e for e in items if e.get('done')],key=lambda e:e.get('completed_at',''),reverse=True)

def num(value,suffix=''):
    try:
        n=float(value)
        if not math.isfinite(n): return '--'
        return str(round(n))+suffix
    except (ValueError,TypeError,OverflowError): return '--'

