def section_frame(title,subtitle=''):
    image=Image.new('L',(600,800),255); d=ImageDraw.Draw(image)
    d.text((30,26),title,font=font(28,True),fill=0,anchor='lt')
    if subtitle: d.text((30,72),fit_text(d,subtitle,17,540),font=font(17),fill=75,anchor='lt')
    d.line((30,105,570,105),fill=0,width=2)
    return image,d

def page_slice(items,page,count=6):
    total=max(1,(len(items)+count-1)//count)
    page=max(0,min(page,total-1))
    return items[page*count:(page+1)*count],page,total

def pager(d,page,total,y=670):
    if page>0:
        icon_button(d,(30,y,182,y+40),'prev',24)
    d.text((300,y+12),f'{page+1} / {total}',font=font(17),fill=70,anchor='mt')
    if page+1<total:
        icon_button(d,(418,y,570,y+40),'next',24)

