POMO_MINUS=(110,581,230,640)
POMO_PLUS=(370,581,490,640)

def render_pomodoro(timer):
    state=timer['state']; remaining=timer['remaining']
    duration=timer.get('duration',2700)
    minutes=max(0,math.ceil(remaining/60))
    label={'idle':'设置时长','running':'专注中 · 保持唤醒','paused':'已暂停','done':'专注完成'}[state]
    image,d=section_frame('番茄钟',label)
    circle=(110,160,490,540)
    fraction=max(0,min(1,remaining/max(1,duration)))
    if state=='idle': d.ellipse(circle,outline=190,width=3)
    elif fraction>=1: d.ellipse(circle,outline=0,width=18)
    elif fraction>0:
        # Pillow angles advance clockwise; erase from noon toward the right.
        d.arc(circle,-90+360*(1-fraction),270,fill=0,width=18)
    d.text((300,239),str(minutes),font=font(130,True,True),fill=0,anchor='mt')
    d.text((300,408),'分钟' if state=='idle' else '分钟剩余' if state!='done' else '休息一下',font=font(27,True),fill=0,anchor='mt')
    if state=='idle':
        icon_button(d,POMO_MINUS,'minus',28,disabled=duration<=300)
        icon_button(d,POMO_PLUS,'plus',28,disabled=duration>=10800)
        d.text((300,600),'5 分钟',font=font(18),fill=75,anchor='mt')
    elif state!='done':
        d.text((300,603),f'本轮 {round(duration/60)} 分钟',font=font(20),fill=75,anchor='mt')
    toggle='暂停' if state=='running' else '继续' if state=='paused' else '开始' if state=='idle' else ''
    if state=='running':
        d.text((300,657),'暂停后可返回看板',font=font(17),fill=85,anchor='mt')
    _draw_buttons(d,('' if state=='running' else '返回',toggle,'重置' if state!='idle' else ''))
    return image

def month_days(year,month):
    weeks=calendar.Calendar(firstweekday=0).monthdayscalendar(year,month)
    return weeks+[[0]*7 for _ in range(6-len(weeks))]

def render_calendar(config,year,month,current=None):
    current=current or now()
    image,d=section_frame('日历',f'{year} 年 {month} 月 · 有圆点的日期含日程')
    for i,label in enumerate('一二三四五六日'):
        d.text((30+(i+0.5)*77,125),label,font=font(20,True),fill=0,anchor='mt')
    counts={}
    for e in config['events']: counts[e['date']]=counts.get(e['date'],0)+1
    for row,week in enumerate(month_days(year,month)):
        for col,day in enumerate(week):
            x=30+col*77; y=165+row*76
            d.rectangle((x,y,x+77,y+76),outline=200,width=1)
            if not day: continue
            today=(year,month,day)==(current.year,current.month,current.day)
            if today: d.ellipse((x+18,y+10,x+58,y+50),fill=0)
            d.text((x+38,y+18),str(day),font=font(23,True,True),fill=255 if today else 0,anchor='mt')
            if counts.get(f'{year:04d}-{month:02d}-{day:02d}'):
                d.ellipse((x+35,y+57,x+41,y+63),fill=0)
    for x,label in ((30,'上个月'),(214,'本月'),(398,'下个月')):
        icon_button(d,(x,660,x+172,707),BUTTON_ICONS[label])
    _draw_buttons(d,('返回','新增','全部日程'))
    return image

def weather_rows(state,current=None):
    current=current or now()
    weather=state.get('weather')
    daily=weather.get('daily') if isinstance(weather,dict) else {}
    if not isinstance(daily,dict) or not isinstance(daily.get('time'),list): return []
    rows=[]
    for i,day in enumerate(daily['time']):
        try: stamp=datetime.strptime(day,'%Y-%m-%d').date()
        except (TypeError,ValueError): continue
        if stamp<current.date(): continue
        row={'date':stamp}
        for name in ('weather_code','temperature_2m_min','temperature_2m_max','precipitation_probability_max'):
            values=daily.get(name)
            row[name]=values[i] if isinstance(values,list) and len(values)>i else None
        rows.append(row)
    return rows[:7]

def render_weather(state,current=None,time_format='24'):
    current=current or now()
    location=state.get('location')
    name=str(location.get('name') or '天气') if isinstance(location,dict) else '天气'
    at=parsed_time(state.get('weather_at'))
    stale=bool(state.get('error')) or not at or (current-at).total_seconds()>1800
    update_text=at.strftime('%m-%d')+' '+clock_text(at,time_format) if at else '等待联网'
    subtitle=('缓存预报 · ' if stale else '更新于 ')+update_text
    if state.get('weather_refreshing'): subtitle='正在刷新天气…'
    image,d=section_frame(fit_text(_MEASURE,name+' · 未来天气',28,540,True),subtitle)
    weather=state.get('weather')
    c=weather.get('current',{}) if isinstance(weather,dict) else {}
    if not isinstance(c,dict): c={}
    d.text((30,124),'现在 '+num(c.get('temperature_2m'),'°')+' · '+weather_name(c.get('weather_code')),font=font(26,True),fill=0,anchor='lt')
    d.text((30,166),'体感 '+num(c.get('apparent_temperature'),'°')+'   湿度 '+num(c.get('relative_humidity_2m'),'%')+'   风速 '+num(c.get('wind_speed_10m'),' km/h'),font=font(17),fill=70,anchor='lt')
    rows=weather_rows(state,current)
    if not rows: d.text((30,260),'暂无未来预报，联网后点刷新图标。',font=font(22),fill=0,anchor='lt')
    for i,row in enumerate(rows):
        y=212+i*64
        day=row['date']
        label='今天' if day==current.date() else ('明天' if day==current.date()+timedelta(days=1) else '周'+'一二三四五六日'[day.weekday()])
        d.text((30,y),label+' '+day.strftime('%m/%d'),font=font(18,True),fill=0,anchor='lt')
        icon(d,row['weather_code'] if isinstance(row['weather_code'],int) else -1,156,y-10,0.48)
        d.text((213,y),weather_name(row['weather_code']),font=font(18),fill=0,anchor='lt')
        d.text((347,y),num(row['temperature_2m_min'])+'～'+num(row['temperature_2m_max'],'°'),font=font(20,True),fill=0,anchor='lt')
        d.text((570,y+3),'降水 '+num(row['precipitation_probability_max'],'%'),font=font(15),fill=70,anchor='rt')
        d.line((30,y+50,570,y+50),fill=205,width=1)
    d.text((30,683),'未来 7 天 · 预报会随更新变化 · Open-Meteo',font=font(15),fill=80,anchor='lt')
    _draw_buttons(d,('返回','刷新',''))
    return image

